---
layout: default
title: Blog
---

<div class="tufte-post">
  <header class="post-header">
    <a class="ornament" href="{{ site.baseurl }}/" aria-label="Home"></a>
    <h1>Posts</h1>
    <p class="subtitle">Tech, Life, Art &amp; Culture</p>
  </header>

  <div class="post-body">
    <div class="lang-filter" id="lang-filter">
      <button class="lang-filter-btn active" data-lang="all">All</button>
      <button class="lang-filter-btn" data-lang="en">English</button>
      <button class="lang-filter-btn" data-lang="my">Burmese</button>
    </div>

    {% assign posts_by_year = site.posts | group_by_exp: "post", "post.date | date: '%Y'" %}
    {% for year in posts_by_year %}
    <div class="blog-year-block" data-year="{{ year.name }}">
      <h2 class="blog-year-heading">{{ year.name }}</h2>
      <ul class="post-list post-links-list">
        {% for post in year.items %}
        <li class="post-list-item{% unless post.lang %} lang-my{% endunless %}" data-post-lang="{% if post.lang %}en{% else %}my{% endif %}">
          <a class="post-list-title" href="{{ site.baseurl }}{{ post.url }}">{{ post.title }}</a>
        </li>
        {% endfor %}
      </ul>
    </div>
    {% endfor %}
  </div>
</div>

<script>
(function() {
  var filterEl = document.getElementById('lang-filter');
  if (!filterEl) return;

  function applyFilter(lang) {
    filterEl.querySelectorAll('.lang-filter-btn').forEach(function(b) {
      b.classList.toggle('active', b.dataset.lang === lang);
    });

    document.querySelectorAll('.blog-year-block').forEach(function(block) {
      var visibleCount = 0;
      block.querySelectorAll('.post-list-item').forEach(function(item) {
        var show = lang === 'all' || item.dataset.postLang === lang;
        item.style.display = show ? '' : 'none';
        if (show) visibleCount++;
      });
      block.style.display = visibleCount > 0 ? '' : 'none';
    });
  }

  filterEl.addEventListener('click', function(e) {
    var btn = e.target.closest('.lang-filter-btn');
    if (!btn) return;
    var lang = btn.dataset.lang;
    applyFilter(lang);
    var url = new URL(window.location);
    if (lang === 'all') { url.searchParams.delete('lang'); }
    else { url.searchParams.set('lang', lang); }
    history.replaceState(null, '', url);
  });

  // Deep-link support: /blog/?lang=en or /blog/?lang=my
  var requested = new URLSearchParams(window.location.search).get('lang');
  if (requested === 'en' || requested === 'my') {
    applyFilter(requested);
  }
})();
</script>

