    <p>I write mainly in English and Burmese.</p>
    <p>Find me on <a href="https://www.linkedin.com/in/wuthmonehninhlaing/" target="_blank">LinkedIn</a> and <a href="https://github.com/alexsnow348" target="_blank">GitHub</a>.</p> 

    {% assign english_posts = site.posts | where_exp: "p", "p.lang != nil" %}
    {% assign burmese_posts = site.posts | where_exp: "p", "p.lang == nil" %}

    <h2>Recent Posts</h2>
    <ul class="post-list home-post-list">
      {% for post in english_posts limit:5 %}
      <li class="post-list-item">
