layout: default
title: Home
---

<div class="tufte-post home-page">
  <header class="post-header">
    <a class="ornament" href="{{ site.baseurl }}/" aria-label="Home"></a>
    <h1>{{ site.author.name }}</h1>
    <p class="subtitle">{{ site.tagline }}</p>
  </header>

  <div class="post-body">
    <span class="side home-portrait">
      <img src="http://www.gravatar.com/avatar/{{ site.author.gravatar }}?s=300" alt="{{ site.author.name }}" />
    </span>

    <p>Hi! This is my personal site.</p>
    <p>I'm an (AI) Solution Architect based in Germany. I write things down for my future self to reflect on my thought processes regarding tech, life, art, and culture. </p>
    <p>I write mainly in English and Burmese.</p>
    <p>Find me on <a href="https://www.linkedin.com/in/wuthmonehninhlaing/" target="_blank">LinkedIn</a> and <a href="https://github.com/alexsnow348" target="_blank">GitHub</a>.</p> 

    {% assign english_posts = site.posts | where_exp: "p", "p.lang != nil" %}
    {% assign burmese_posts = site.posts | where_exp: "p", "p.lang == nil" %}

    <h2>Recent Posts</h2>
    <ul class="post-list home-post-list">
      {% for post in english_posts limit:5 %}
      <li class="post-list-item">
        <a class="post-list-title" href="{{ site.baseurl }}{{ post.url }}">{{ post.title }}</a>
        <span class="post-list-date">
          {% if post.lang == "de" %}
            {% assign de_month_key = post.date | date: "%m" %}
            {{ post.date | date: "%-d" }}. {{ site.data.de_months[de_month_key] }} {{ post.date | date: "%Y" }}
          {% else %}
            {{ post.date | date: "%B %-d, %Y" }}
          {% endif %}
          {% if post.tags.size > 0 %}
          &middot; <span class="tags">{% for tag in post.tags %}{{ tag }}{% unless forloop.last %} &middot; {% endunless %}{% endfor %}</span>
          {% elsif post.categories.size > 0 %}
          &middot; <span class="tags">{% for tag in post.categories %}{{ tag }}{% unless forloop.last %} &middot; {% endunless %}{% endfor %}</span>
          {% endif %}
        </span>
        {% if post.description %}
        <span class="post-list-desc">{{ post.description }}</span>
        {% endif %}
      </li>
      {% endfor %}
    </ul>
    <p><a href="{{ site.baseurl }}/blog/?lang=en">All posts &rarr;</a></p>

    <h2>Recent Posts (Burmese)</h2>
    <div class="posts legacy-posts">
      {% for post in burmese_posts limit:5 %}
      <div class="post">
        <h2 class="post-title"><a href="{{ site.baseurl }}{{ post.url }}">{{ post.title }}</a></h2>
        <span class="post-date">
          {{ post.date | date_to_string }}
          {% if post.categories.size > 0 %}
          &middot; {% for tag in post.categories %}<a class="post-tag">{{ tag }}</a>{% endfor %}
          {% endif %}
        </span>
      </div>
      {% endfor %}
    </div>
    <p><a href="{{ site.baseurl }}/blog/?lang=my">All posts &rarr;</a></p>
  </div>
</div>
